<script setup lang="ts">
import { LoaderCircle, Plus, Search, UsersRound, X } from 'lucide-vue-next'
definePageMeta({ middleware: 'auth' }); useHead({ title: 'Clubes — ChessDuel' })
type Club={id:string;name:string;description:string;avatar_url:string|null;join_policy:'open'|'approval';member_count:number}
type ListResponse={clubs:Club[];pagination:{page:number;per_page:number;total:number;total_pages:number}}
const auth=useAuthStore(),config=useRuntimeConfig(),route=useRoute()
const clubs=ref<Club[]>([]),pagination=ref({page:1,per_page:12,total:0,total_pages:1}),loading=ref(true),searchPending=ref(false),error=ref(''),createOpen=ref(false),saving=ref(false),formError=ref(''),file=ref<File|null>(null)
const form=reactive({name:'',description:'',join_policy:'approval' as 'open'|'approval'}),query=ref(String(route.query.q||'')),page=computed(()=>Math.max(1,Number(route.query.page)||1)),headers=computed(()=>({Authorization:`Bearer ${auth.token}`}))
let searchTimer:ReturnType<typeof setTimeout>|undefined,loadVersion=0
watch(()=>route.fullPath,()=>{const routeQuery=String(route.query.q||'');if(query.value!==routeQuery)query.value=routeQuery;void load()},{immediate:true})
watch(query,value=>{clearTimeout(searchTimer);const term=value.trim();if(term===String(route.query.q||'')){searchPending.value=false;return}searchPending.value=true;searchTimer=setTimeout(()=>{searchPending.value=false;void navigateTo({path:'/social/clubs',query:{...(term?{q:term}:{})}},{replace:true})},350)})
async function load(){const version=++loadVersion;loading.value=true;error.value='';try{const data=await $fetch<ListResponse>('/api/clubs',{baseURL:config.public.api.baseURL,query:{q:route.query.q,page:page.value},headers:headers.value});if(version===loadVersion){clubs.value=data.clubs;pagination.value=data.pagination}}catch(e){if(version===loadVersion)error.value=message(e)}finally{if(version===loadVersion)loading.value=false}}
function go(next:number){navigateTo({path:'/social/clubs',query:{...(route.query.q?{q:String(route.query.q)}:{}),...(next>1?{page:next}:{})}})}
function onFile(event:Event){file.value=(event.target as HTMLInputElement).files?.[0]||null}
function message(e:unknown){const data=(e as {data?:{message?:string;errors?:Record<string,string[]>}})?.data;return data?.message||Object.values(data?.errors||{}).flat()[0]||'Não foi possível concluir a operação.'}
async function createClub(){saving.value=true;formError.value='';try{const body=new FormData();body.append('club[name]',form.name);body.append('club[description]',form.description);body.append('club[join_policy]',form.join_policy);if(file.value)body.append('avatar',file.value);const result=await $fetch<{club:Club}>('/api/clubs',{baseURL:config.public.api.baseURL,method:'POST',headers:headers.value,body});await navigateTo(`/social/clubs/${result.club.id}`)}catch(e){formError.value=message(e)}finally{saving.value=false}}
onBeforeUnmount(()=>{clearTimeout(searchTimer);++loadVersion})
</script>
<template><main class="clubs-page">
  <header class="heading"><div><p>Social</p><h1>Clubes</h1><span>Encontre grupos e jogue ao lado da sua comunidade.</span></div><button class="primary" @click="createOpen=true"><Plus :size="18"/>Criar clube</button></header>
  <form class="search" role="search" @submit.prevent><label for="club-search">Buscar clube por nome</label><div class="search-field" :aria-busy="searchPending||loading"><Search :size="18" aria-hidden="true"/><input id="club-search" v-model="query" type="search" maxlength="80" placeholder="Nome do clube" autocomplete="off"><LoaderCircle v-if="searchPending||loading" class="spinner" :size="18" aria-label="Buscando clubes"/></div></form>
  <p v-if="error" class="feedback error" role="alert">{{ error }}</p><p v-if="loading&&!clubs.length" class="state" role="status">Carregando clubes…</p>
  <section v-else-if="clubs.length" class="grid" aria-label="Clubes encontrados" :aria-busy="loading"><NuxtLink v-for="club in clubs" :key="club.id" :to="`/social/clubs/${club.id}`" class="card"><ClubsClubAvatar :name="club.name" :avatar-url="club.avatar_url"/><div><h2>{{ club.name }}</h2><p>{{ club.description||'Este clube ainda não adicionou uma descrição.' }}</p><span><UsersRound :size="15"/>{{ club.member_count }} membro(s) · {{ club.join_policy==='open'?'Entrada aberta':'Por aprovação' }}</span></div></NuxtLink></section>
  <p v-else-if="!loading" class="state">Nenhum clube encontrado. Você pode criar o primeiro.</p>
  <nav v-if="pagination.total_pages>1" class="pagination" aria-label="Paginação"><button :disabled="page===1" @click="go(page-1)">Anterior</button><span>Página {{ page }} de {{ pagination.total_pages }}</span><button :disabled="page===pagination.total_pages" @click="go(page+1)">Próxima</button></nav>
  <div v-if="createOpen" class="overlay" @click.self="createOpen=false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="create-title" @keydown.esc="createOpen=false"><header><h2 id="create-title">Criar clube</h2><button aria-label="Fechar" @click="createOpen=false"><X :size="20"/></button></header><form @submit.prevent="createClub"><label>Nome<input v-model="form.name" required minlength="3" maxlength="80"></label><label>Descrição<textarea v-model="form.description" maxlength="1000" rows="4"/></label><fieldset><legend>Política de entrada</legend><label><input v-model="form.join_policy" type="radio" value="open">Aberta — entrada imediata</label><label><input v-model="form.join_policy" type="radio" value="approval">Por aprovação de administrador</label></fieldset><label>Avatar opcional<input type="file" accept="image/png,image/jpeg,image/webp" @change="onFile"></label><p v-if="formError" class="feedback error" role="alert">{{ formError }}</p><button class="primary" :disabled="saving">{{ saving?'Criando…':'Criar clube' }}</button></form></section></div>
</main></template>
<style scoped>
.clubs-page{width:min(1080px,calc(100% - 2rem));margin:auto;padding:2.5rem 0 4rem;color:var(--text)}.heading{display:flex;align-items:end;justify-content:space-between;gap:1rem;margin-bottom:1.5rem}.heading p{margin:0;color:var(--accent);font-weight:800}.heading h1{margin:.35rem 0;font-size:2.2rem}.heading span,.card p,.card span{color:var(--text-muted)}button{display:inline-flex;align-items:center;justify-content:center;gap:.45rem;padding:.72rem 1rem;color:var(--text);background:var(--surface-strong);border:1px solid var(--border);border-radius:9px;cursor:pointer}button:hover:not(:disabled){background:var(--surface-hover)}button.primary{color:var(--accent-ink);background:var(--accent);border-color:var(--accent)}button.primary:hover{background:var(--accent-hover)}button:disabled{opacity:.55;cursor:default}.search{padding:1.25rem;margin-bottom:1.3rem;background:var(--surface);border:1px solid var(--border);border-radius:14px}.search>label{display:block;margin-bottom:.45rem;color:var(--text-muted);font-size:.86rem}.search>.search-field{display:flex;align-items:center;gap:.65rem;padding:0 .8rem;color:var(--text-muted);background:var(--bg);border:1px solid var(--border);border-radius:8px}.search-field:focus-within{border-color:var(--accent);box-shadow:0 0 0 2px color-mix(in srgb,var(--accent) 20%,transparent)}.search-field input{flex:1;padding:.75rem 0;background:transparent;border:0;outline:0}.spinner{flex:0 0 auto;color:var(--accent);animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem;transition:opacity 160ms ease}.grid[aria-busy="true"]{opacity:.62}.card{display:flex;gap:1rem;padding:1.25rem;color:var(--text);background:var(--surface);border:1px solid var(--border);border-radius:14px;text-decoration:none}.card:hover{border-color:var(--accent);background:var(--surface-hover)}.card h2{margin:0;font-size:1.08rem}.card p{display:-webkit-box;min-height:2.6em;overflow:hidden;-webkit-line-clamp:2;-webkit-box-orient:vertical;margin:.4rem 0}.card span{display:flex;align-items:center;gap:.35rem;font-size:.8rem}.state,.feedback{padding:2rem;text-align:center;color:var(--text-muted);background:var(--surface);border:1px solid var(--border);border-radius:14px}.feedback.error{color:var(--danger);background:var(--danger-soft)}.pagination{display:flex;align-items:center;justify-content:center;gap:1rem;margin-top:1.5rem;color:var(--text-muted)}input,textarea{width:100%;padding:.75rem;color:var(--text);background:var(--bg);border:1px solid var(--border);border-radius:8px}.overlay{position:fixed;z-index:100;inset:0;display:grid;place-items:center;padding:1rem;background:rgb(0 0 0/60%)}.modal{width:min(560px,100%);max-height:calc(100vh - 2rem);overflow:auto;padding:1.3rem;background:var(--surface);border:1px solid var(--border);border-radius:16px;box-shadow:var(--shadow)}.modal>header{display:flex;align-items:center;justify-content:space-between}.modal h2{margin:0}.modal form{display:grid;gap:1rem;margin-top:1rem}.modal label{display:grid;gap:.4rem;color:var(--text-muted);font-size:.9rem}.modal fieldset{display:grid;gap:.6rem;padding:1rem;border:1px solid var(--border);border-radius:10px}.modal fieldset label{display:flex}.modal fieldset input{width:auto}@media(max-width:650px){.heading{align-items:stretch;flex-direction:column}.grid{grid-template-columns:1fr}.pagination{justify-content:space-between}}
</style>
